  "Free access does not cancel an existing Apple subscription. Cancel it in iPhone Settings → your name → Subscriptions to stop future renewals.": "無料アクセスを有効にしても、契約中のAppleサブスクリプションは自動解約されません。次回以降の更新を止めるには、iPhoneの「設定」→自分の名前→「サブスクリプション」から解約してください。",
